#include <Adafruit_NeoPixel.h>

// Настройка пинов
#define FRONT_LEFT_PIN 6      // Пин для передней левой ленты
#define FRONT_RIGHT_PIN 7     // Пин для передней правой ленты
#define REAR_LEFT_PIN 8       // Пин для задней левой ленты
#define REAR_RIGHT_PIN 9      // Пин для задней правой ленты

#define LEFT_BUTTON_PIN 2     // Кнопка левого поворота
#define RIGHT_BUTTON_PIN 3    // Кнопка правого поворота
#define BRAKE_PIN 4           // Сигнал торможения
#define HAZARD_BUTTON_PIN 5   // Кнопка аварийки

// Настройка лент
#define NUM_LEDS 30           // Количество светодиодов в каждой ленте
#define BRIGHTNESS 50         // Яркость (0-255)

// Настройка анимации
#define BLINK_COUNT 3         // Количество миганий (настраиваемое)
#define BLINK_DELAY 100       // Задержка между кадрами анимации (мс)
#define ANIMATION_SPEED 30    // Скорость бегущей анимации (мс)

// Создаем объекты для лент
Adafruit_NeoPixel frontLeftStrip(NUM_LEDS, FRONT_LEFT_PIN, NEO_GRB + NEO_KHZ800);
Adafruit_NeoPixel frontRightStrip(NUM_LEDS, FRONT_RIGHT_PIN, NEO_GRB + NEO_KHZ800);
Adafruit_NeoPixel rearLeftStrip(NUM_LEDS, REAR_LEFT_PIN, NEO_GRB + NEO_KHZ800);
Adafruit_NeoPixel rearRightStrip(NUM_LEDS, REAR_RIGHT_PIN, NEO_GRB + NEO_KHZ800);

// Состояния
bool leftTurnActive = false;
bool rightTurnActive = false;
bool hazardActive = false;
bool brakeActive = false;
bool brakeWasActive = false;

unsigned long lastAnimationTime = 0;
int currentLED = 0;
int blinkCounter = 0;
bool animationPhase = false;  // false - заполнение, true - пауза

// Цвета
uint32_t amberColor;  // Янтарный для поворотников
uint32_t redColor;    // Красный для торможения
uint32_t offColor;    // Выключено

void setup() {
  Serial.begin(9600);

  // Инициализация пинов
  pinMode(LEFT_BUTTON_PIN, INPUT_PULLUP);
  pinMode(RIGHT_BUTTON_PIN, INPUT_PULLUP);
  pinMode(BRAKE_PIN, INPUT_PULLUP);
  pinMode(HAZARD_BUTTON_PIN, INPUT_PULLUP);

  // Инициализация всех лент
  frontLeftStrip.begin();
  frontRightStrip.begin();
  rearLeftStrip.begin();
  rearRightStrip.begin();

  // Устанавливаем яркость
  frontLeftStrip.setBrightness(BRIGHTNESS);
  frontRightStrip.setBrightness(BRIGHTNESS);
  rearLeftStrip.setBrightness(BRIGHTNESS);
  rearRightStrip.setBrightness(BRIGHTNESS);

  // Определяем цвета
  amberColor = frontLeftStrip.Color(255, 140, 0);  // Янтарный
  redColor = rearLeftStrip.Color(255, 0, 0);       // Красный
  offColor = frontLeftStrip.Color(0, 0, 0);        // Выключено

  // Очищаем все ленты
  clearAllStrips();

  Serial.println("Система готова!");
  Serial.println("Команды:");
  Serial.println("SET_BLINKS:3 - установить количество миганий");
  Serial.println("LEFT - левый поворот");
  Serial.println("RIGHT - правый поворот");
  Serial.println("HAZARD - аварийка");
  Serial.println("STOP - остановить все");
}

void loop() {
  // Чтение кнопок
  readButtons();

  // Обработка Serial команд
  handleSerialCommands();

  // Обработка торможения
  handleBrake();

  // Обработка поворотников
  handleTurnSignals();

  // Обновление анимации
  updateAnimation();
}

void readButtons() {
  // Проверка кнопки левого поворота
  if (digitalRead(LEFT_BUTTON_PIN) == LOW) {
    delay(50); // Дебаунс
    if (digitalRead(LEFT_BUTTON_PIN) == LOW) {
      if (!leftTurnActive && !hazardActive) {
        startLeftTurn();
      }
      while (digitalRead(LEFT_BUTTON_PIN) == LOW); // Ждем отпускания
    }
  }

  // Проверка кнопки правого поворота
  if (digitalRead(RIGHT_BUTTON_PIN) == LOW) {
    delay(50);
    if (digitalRead(RIGHT_BUTTON_PIN) == LOW) {
      if (!rightTurnActive && !hazardActive) {
        startRightTurn();
      }
      while (digitalRead(RIGHT_BUTTON_PIN) == LOW);
    }
  }

  // Проверка кнопки аварийки
  if (digitalRead(HAZARD_BUTTON_PIN) == LOW) {
    delay(50);
    if (digitalRead(HAZARD_BUTTON_PIN) == LOW) {
      toggleHazard();
      while (digitalRead(HAZARD_BUTTON_PIN) == LOW);
    }
  }
}

void startLeftTurn() {
  leftTurnActive = true;
  rightTurnActive = false;
  currentLED = 0;
  blinkCounter = 0;
  animationPhase = false;
  lastAnimationTime = 0;  // Сброс таймера
  Serial.println("Левый поворот включен");
}

void startRightTurn() {
  rightTurnActive = true;
  leftTurnActive = false;
  currentLED = 0;
  blinkCounter = 0;
  animationPhase = false;
  lastAnimationTime = 0;  // Сброс таймера
  Serial.println("Правый поворот включен");
}

void toggleHazard() {
  hazardActive = !hazardActive;
  if (hazardActive) {
    leftTurnActive = false;
    rightTurnActive = false;
    currentLED = 0;
    blinkCounter = 0;
    animationPhase = false;
    lastAnimationTime = 0;  // Сброс таймера
    Serial.println("Аварийка включена");
  } else {
    hazardActive = false;
    clearAllStrips();
    // Восстанавливаем красный цвет при торможении
    if (brakeActive) {
      fillRearStrips(redColor);
      rearLeftStrip.show();
      rearRightStrip.show();
    }
    Serial.println("Аварийка выключена");
  }
}

void handleBrake() {
  brakeActive = (digitalRead(BRAKE_PIN) == LOW);

  // Если состояние тормоза изменилось
  if (brakeActive != brakeWasActive) {
    brakeWasActive = brakeActive;

    if (brakeActive) {
      Serial.println("Тормоз нажат");
    } else {
      Serial.println("Тормоз отпущен");
    }
  }

  // Обновляем состояние лент только если нет активной анимации
  if (!leftTurnActive && !rightTurnActive && !hazardActive) {
    if (brakeActive) {
      // Зажигаем обе задние ленты красным
      fillRearStrips(redColor);
      rearLeftStrip.show();
      rearRightStrip.show();

      // Очищаем передние ленты
      clearFrontStrips();
      frontLeftStrip.show();
      frontRightStrip.show();
    } else {
      clearAllStrips();
    }
  }
}

void handleTurnSignals() {
  if (leftTurnActive || rightTurnActive || hazardActive) {
    // Проверяем, не пора ли завершить мигание
    if (blinkCounter >= BLINK_COUNT * 2 && !hazardActive) {
      // Завершаем поворот
      leftTurnActive = false;
      rightTurnActive = false;

      // Восстанавливаем состояние лент
      if (brakeActive) {
        // При торможении задние ленты красные
        fillRearStrips(redColor);
        rearLeftStrip.show();
        rearRightStrip.show();
        clearFrontStrips();
        frontLeftStrip.show();
        frontRightStrip.show();
      } else {
        clearAllStrips();
      }

      Serial.println("Поворот завершен");
    }
  }
}

void updateAnimation() {
  unsigned long currentTime = millis();

  if (!leftTurnActive && !rightTurnActive && !hazardActive) {
    return;  // Нет активной анимации
  }

  // Проверяем таймер
  if (currentTime - lastAnimationTime < ANIMATION_SPEED) {
    return;  // Еще рано для следующего кадра
  }

  lastAnimationTime = currentTime;

  // Определяем активные ленты
  bool leftActive = leftTurnActive || hazardActive;
  bool rightActive = rightTurnActive || hazardActive;

  // Очищаем все ленты
  clearAllStrips();

  // Если тормоз нажат, заполняем задние ленты красным
  if (brakeActive) {
    fillRearStrips(redColor);
  }

  // Рисуем анимацию поворотников
  if (animationPhase) {
    // Фаза паузы - все выключено (кроме тормозных огней)
    if (brakeActive) {
      fillRearStrips(redColor);
      rearLeftStrip.show();
      rearRightStrip.show();
    }
  } else {
    // Фаза заполнения
    for (int i = 0; i <= currentLED && i < NUM_LEDS; i++) {
      if (leftActive) {
        // Передняя левая лента - янтарный
        frontLeftStrip.setPixelColor(i, amberColor);
        // Задняя левая лента - янтарный
        rearLeftStrip.setPixelColor(i, amberColor);
      }

      if (rightActive) {
        // Передняя правая лента - янтарный
        frontRightStrip.setPixelColor(NUM_LEDS - 1 - i, amberColor);
        // Задняя правая лента - янтарный
        rearRightStrip.setPixelColor(NUM_LEDS - 1 - i, amberColor);
      }
    }
  }

  // Показываем все ленты
  frontLeftStrip.show();
  frontRightStrip.show();
  rearLeftStrip.show();
  rearRightStrip.show();

  // Обновляем счетчики
  currentLED++;

  // Когда анимация дошла до конца
  if (currentLED >= NUM_LEDS) {
    currentLED = 0;
    blinkCounter++;

    // Переключаем фазу
    animationPhase = !animationPhase;

    // Если это была фаза заполнения, добавляем паузу
    if (!animationPhase && blinkCounter < BLINK_COUNT * 2) {
      // Короткая пауза между миганиями
      lastAnimationTime = currentTime - ANIMATION_SPEED + BLINK_DELAY;
    }
  }
}

// Функции для работы с лентами
void clearAllStrips() {
  clearFrontStrips();
  clearRearStrips();
  frontLeftStrip.show();
  frontRightStrip.show();
  rearLeftStrip.show();
  rearRightStrip.show();
}

void clearFrontStrips() {
  for (int i = 0; i < NUM_LEDS; i++) {
    frontLeftStrip.setPixelColor(i, offColor);
    frontRightStrip.setPixelColor(i, offColor);
  }
}

void clearRearStrips() {
  for (int i = 0; i < NUM_LEDS; i++) {
    rearLeftStrip.setPixelColor(i, offColor);
    rearRightStrip.setPixelColor(i, offColor);
  }
}

void fillRearStrips(uint32_t color) {
  for (int i = 0; i < NUM_LEDS; i++) {
    rearLeftStrip.setPixelColor(i, color);
    rearRightStrip.setPixelColor(i, color);
  }
}

void fillFrontStrips(uint32_t color) {
  for (int i = 0; i < NUM_LEDS; i++) {
    frontLeftStrip.setPixelColor(i, color);
    frontRightStrip.setPixelColor(i, color);
  }
}

// Функция для настройки количества миганий через Serial
void handleSerialCommands() {
  if (Serial.available()) {
    String command = Serial.readStringUntil('\n');
    command.trim();

    if (command.startsWith("SET_BLINKS:")) {
      int count = command.substring(11).toInt();
      if (count > 0 && count <= 10) {
        // Здесь можно сохранить в EEPROM
        // const_cast<int&>(BLINK_COUNT) = count; // Нельзя изменить const
        Serial.print("Количество миганий установлено: ");
        Serial.println(count);
        Serial.println("Примечание: измените BLINK_COUNT в коде и перезагрузите");
      }
    } else if (command == "LEFT") {
      startLeftTurn();
    } else if (command == "RIGHT") {
      startRightTurn();
    } else if (command == "HAZARD") {
      toggleHazard();
    } else if (command == "STOP") {
      leftTurnActive = false;
      rightTurnActive = false;
      hazardActive = false;
      clearAllStrips();
      if (brakeActive) {
        fillRearStrips(redColor);
        rearLeftStrip.show();
        rearRightStrip.show();
      }
      Serial.println("Все остановлено");
    }
  }
}
